create index if not exists fire_detections_date_sensor_location_idx on public.fire_detections (acq_date, sensor, satellite, lat, lon);
create index if not exists fire_detections_location_date_idx on public.fire_detections (lat, lon, acq_date);

create or replace function public.monthly_series(p_west double precision,p_south double precision,p_east double precision,p_north double precision,p_from_date date,p_to_date date)
returns table(month date,sensor_group text,raw_detections bigint,burning_cell_days bigint,days_with_detections bigint,nrt_share double precision)
language sql stable security invoker set search_path = public as $fn$
with months as (select generate_series(date_trunc('month',p_from_date)::date,date_trunc('month',p_to_date)::date,interval '1 month')::date as month), groups as (select unnest(array['MODIS','VIIRS_SNPP','VIIRS_N20'])::text as sensor_group), grouped as (select date_trunc('month',fd.acq_date)::date as month,case when fd.sensor='MODIS' then 'MODIS' when fd.sensor='VIIRS' and coalesce(fd.satellite,'') in ('N20','J1','NOAA-20') then 'VIIRS_N20' when fd.sensor='VIIRS' then 'VIIRS_SNPP' end as sensor_group,count(*)::bigint as raw_detections,count(distinct (floor(fd.lon/0.15)::int,floor(fd.lat/0.15)::int,fd.acq_date))::bigint as burning_cell_days,count(distinct fd.acq_date)::bigint as days_with_detections,count(*) filter (where fd.processing='NRT')::double precision/nullif(count(*)::double precision,0) as nrt_share from public.fire_detections fd where fd.lon between p_west and p_east and fd.lat between p_south and p_north and fd.acq_date between p_from_date and p_to_date group by 1,2) select m.month,g.sensor_group,coalesce(x.raw_detections,0),coalesce(x.burning_cell_days,0),coalesce(x.days_with_detections,0),coalesce(x.nrt_share,0) from months m cross join groups g left join grouped x on x.month=m.month and x.sensor_group=g.sensor_group order by m.month,g.sensor_group;
$fn$;

create or replace function public.daily_series(p_west double precision,p_south double precision,p_east double precision,p_north double precision,p_from_date date,p_to_date date)
returns table(day date,sensor_group text,raw_detections bigint,burning_cell_days bigint,days_with_detections bigint,nrt_share double precision)
language sql stable security invoker set search_path = public as $fn$
with days as (select generate_series(p_from_date,p_to_date,interval '1 day')::date as day), groups as (select unnest(array['MODIS','VIIRS_SNPP','VIIRS_N20'])::text as sensor_group), grouped as (select fd.acq_date as day,case when fd.sensor='MODIS' then 'MODIS' when fd.sensor='VIIRS' and coalesce(fd.satellite,'') in ('N20','J1','NOAA-20') then 'VIIRS_N20' when fd.sensor='VIIRS' then 'VIIRS_SNPP' end as sensor_group,count(*)::bigint as raw_detections,count(distinct (floor(fd.lon/0.15)::int,floor(fd.lat/0.15)::int,fd.acq_date))::bigint as burning_cell_days,1::bigint as days_with_detections,count(*) filter (where fd.processing='NRT')::double precision/nullif(count(*)::double precision,0) as nrt_share from public.fire_detections fd where fd.lon between p_west and p_east and fd.lat between p_south and p_north and fd.acq_date between p_from_date and p_to_date group by 1,2) select d.day,g.sensor_group,coalesce(x.raw_detections,0),coalesce(x.burning_cell_days,0),coalesce(x.days_with_detections,0),coalesce(x.nrt_share,0) from days d cross join groups g left join grouped x on x.day=d.day and x.sensor_group=g.sensor_group order by d.day,g.sensor_group;
$fn$;

grant execute on function public.monthly_series(double precision,double precision,double precision,double precision,date,date) to anon,authenticated,service_role;
grant execute on function public.daily_series(double precision,double precision,double precision,double precision,date,date) to anon,authenticated,service_role;
